/* eslint-disable @next/next/no-img-element -- the card is generated by the ifoto route next to this page */
import { ArrowRight, Split, Target } from "lucide-react";
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Suspense } from "react";

import { ButtonLink } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { formatDayLong } from "@/lib/format";
import { fetchSharedResult } from "@/lib/shared-result";
import { pageShare } from "@/lib/site";

const DESCRIPTION = "Ikizamini cy’igerageza cy’amategeko y’umuhanda kuri Tsinda Neza. Nawe witoze ku buntu, mu Kinyarwanda.";

export async function generateMetadata({ params }: PageProps<"/natsinze/[code]">): Promise<Metadata> {
  const { code } = await params;
  const result = await fetchSharedResult(code);
  if (!result) return { title: { absolute: "Tsinda Neza" }, robots: { index: false } };
  const title = `${result.name} yabonye ${result.score}/${result.total} kuri Tsinda Neza`;
  return {
    title: { absolute: title },
    description: DESCRIPTION,
    robots: { index: false },
    ...pageShare(title, DESCRIPTION, `/natsinze/${code}/ifoto`),
  };
}

async function SharedCard({ params }: { params: PageProps<"/natsinze/[code]">["params"] }) {
  const { code } = await params;
  const result = await fetchSharedResult(code);
  if (!result) notFound();
  return (
    <div className="mx-auto max-w-3xl">
      <img
        src={`/natsinze/${code}/ifoto`}
        alt={`${result.name} yabonye ${result.score}/${result.total}`}
        width={1200}
        height={630}
        className="w-full rounded-3xl shadow-lift"
      />
      <div className="mt-8 text-center">
        <h1 className="text-3xl font-extrabold sm:text-4xl">
          {result.passed ? `${result.name} yatsinze ikizamini cy’igerageza!` : `${result.name} yakoze ikizamini cy’igerageza`}
        </h1>
        <p className="mx-auto mt-3 max-w-xl text-lg text-muted">
          Yabonye {result.score}/{result.total} ku wa {formatDayLong(result.day)}, yitoza kuri Tsinda Neza: amasomo, ibyapa
          n’ibizamini bimeze nk’ibya Polisi, mu Kinyarwanda.
        </p>
        <div className="mt-8 flex flex-col justify-center gap-3 sm:flex-row">
          <ButtonLink href="/injira" size="lg">
            Nawe tangira ku buntu <ArrowRight className="size-5" />
          </ButtonLink>
          <ButtonLink href="/#gerageza" size="lg" variant="secondary">
            <Target className="size-5" /> Gerageza ibibazo 5
          </ButtonLink>
          <ButtonLink href="/imyitozo/ninde-utambuka" size="lg" variant="secondary">
            <Split className="size-5" /> Ninde utambuka mbere?
          </ButtonLink>
        </div>
      </div>
    </div>
  );
}

/** Public page behind a shared result link. Its preview picture is the result card. */
export default function SharedResultPage({ params }: PageProps<"/natsinze/[code]">) {
  return (
    <div className="container-page py-10 sm:py-16">
      <Suspense fallback={<Skeleton className="mx-auto aspect-[1200/630] max-w-3xl rounded-3xl" />}>
        <SharedCard params={params} />
      </Suspense>
    </div>
  );
}
